/*Table structure for table `surat_masuk` */

DROP TABLE IF EXISTS `surat_masuk`;

CREATE TABLE `surat_masuk` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `no_agenda` varchar(50) NOT NULL COMMENT 'Nomor agenda internal',
  `no_surat` varchar(100) NOT NULL COMMENT 'Nomor surat resmi',
  `tgl_surat` date NOT NULL COMMENT 'Tanggal surat',
  `tgl_terima` date NOT NULL COMMENT 'Tanggal diterima',
