  `prioritas` enum('biasa','penting','rahasia') NOT NULL DEFAULT 'biasa' COMMENT 'Prioritas surat',
  `sifat` enum('segera','sangat segera','biasa') NOT NULL DEFAULT 'biasa' COMMENT 'sifat surat',
  `klasifikasi` varchar(255) DEFAULT NULL,
  `file` varchar(255) NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `file_mime` varchar(255) DEFAULT NULL,
  `status` enum('baru','proses','selesai','arsip') NOT NULL DEFAULT 'baru' COMMENT 'Status surat',
  `created_by` bigint(20) unsigned NOT NULL COMMENT 'User ID SDI',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `surat_masuk_no_agenda_unique` (`no_agenda`) USING BTREE,
  KEY `surat_masuk_created_by_foreign` (`created_by`) USING BTREE,
  CONSTRAINT `surat_masuk_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;

